const tbDomLibre=()=>`${tbH("Emplacement libre","Le tableau est extensible : chaque cadran est un module déclaré dans une liste.")}<div class="box"><h4>Ajouter un cadran (pour le chef d'équipe)</h4><ol class="steps"><li>Dans <code>modules/tableau.js</code>, ajouter un objet dans <code>TB_CADRANS</code> : <code>id</code>, <code>titre</code>, <code>ico</code>, <code>etat()</code> (règle vert / orange / rouge + alertes), <code>carte()</code> (le condensé) et <code>domaine()</code> (l'écran complet).</li><li>S'il lit une nouvelle source : ajouter sa lecture dans <code>Tableau.gs</code> (fonction <code>pull</code>) ou une ligne dans l'onglet « Indicateurs » du Sheet.</li><li>Rien d'autre à toucher : la grille, les alertes et le mode bureau le prennent tout seuls.</li></ol></div>`;
TB_CADRANS.libre={domaine:tbDomLibre};

/* ---------- synchronisation (lecture toutes les 5 min, écriture par file hors ligne) ---------- */
async function tbFlush(){const q=(await AtelierCore.kv.get("tableau_q"))||[];if(!q.length)return 0;const j=await AtelierCore.call("tableau.push",{ops:q.map(o=>({opId:o.opId,coll:o.coll,id:o.id,doc:o.doc}))});const res=j.results||[];const keep=q.filter(op=>{const r=res.find(x=>x.opId===op.opId);return !(r&&(r.ok||r.permanent))});const ref=res.filter(r=>r.permanent);if(ref.length)toast(`${ref.length} saisie(s) du tableau refusée(s) : ${ref[0].err}`);await AtelierCore.kv.set("tableau_q",keep);return q.length-keep.length}
async function tbPull(manual){
  if(S.role!=="guide"||!App.key||!App.gw){if(manual)toast(App.gw?"Ouvre d'abord l'appli avec ton QR d'accès.":"La passerelle n'est pas encore installée.");return}
  if(TB.busy)return;if(!App.online()){if(manual)toast("Pas de réseau : derniers chiffres gardés.");return}
  TB.busy=true;if(S.view==="tableau"&&!TB.open)tbRender();
  try{await tbFlush();const j=await AtelierCore.call("tableau.pull",{});TB.d=j.tableau||{};TB.at=Date.now();TB.err=null;await AtelierCore.kv.set("tableau",{d:TB.d,at:TB.at});
    if(!TB.carte||(TB.d.carteVersion&&TB.carte.version!==TB.d.carteVersion)){try{const c=await AtelierCore.call("tableau.carte",{});if(c.carte&&c.carte.pays){TB.carte=c.carte;await AtelierCore.kv.set("tableau_carte",c.carte)}}catch(e){}}}
  catch(e){TB.err=e;if(manual)toast(e.code==="auth"?"Accès refusé : demande un nouveau QR.":e.code==="forbidden"?"Le tableau de bord est réservé au guide.":"Le Drive ne répond pas : derniers chiffres gardés.")}
  finally{TB.busy=false;if(S.view==="tableau")tbRender()}
}
async function tbWrite(coll,id,doc){const op={opId:AtelierCore.newId(),coll,id,doc,at:new Date().toISOString()};const q=(await AtelierCore.kv.get("tableau_q"))||[];q.push(op);await AtelierCore.kv.set("tableau_q",q);tbApplyLocal(op);if(TB.d)await AtelierCore.kv.set("tableau",{d:TB.d,at:TB.at});tbRender();if(App.online())tbPull(false);else toast("Gardé sur ce téléphone, part au Drive dès que le réseau revient.")}
function tbApplyLocal(op){const d=TB.d||(TB.d={});const doc=op.doc||{},id=op.id;const up=(arr,o)=>{const i=arr.findIndex(x=>x.id===id);if(i>=0)Object.assign(arr[i],o);else arr.push(Object.assign({id},o))};
  if(op.coll==="inscrits"){d.raids=d.raids||{liste:[],orphelins:[]};const all=tbInscrits();const cur=all.find(p=>p.id===id)||{};const nd=Object.assign({},cur,doc,{id});const nom=nd.pilote||nd.nom;
    d.raids.liste.forEach(r=>{r.pilotes=(r.pilotes||[]).filter(p=>p.id!==id)});d.raids.orphelins=(d.raids.orphelins||[]).filter(p=>p.id!==id);
    if((nd.statut||"inscrit")!=="annulé"){const r=d.raids.liste.find(x=>x.id===(nd.raidId||cur.raidId));const p={id,nom,acompte:!!nd.acompte,solde:!!nd.solde,kove:!!nd.kove};if(r)r.pilotes.push(p);else d.raids.orphelins.push(Object.assign(p,{raid:nd.raid||cur.raid||""}))}
    d.raids.liste.forEach(r=>{r.inscrits=r.pilotes.length;r.acomptes=r.pilotes.filter(p=>p.acompte).length;r.soldes=r.pilotes.filter(p=>p.solde).length;r.kove=r.pilotes.filter(p=>p.kove).length;r.complet=r.inscrits>=TB_CFG.raidMax;r.etat=tbRaidEtat(r)})}
  else if(op.coll==="prospects"){d.prospects=d.prospects||{liste:[]};up(d.prospects.liste,doc);const td=today(),act=d.prospects.liste.filter(x=>(x.statut||"en cours")==="en cours");Object.assign(d.prospects,{liste:act,aujourdhui:act.filter(x=>x.prochaine&&x.prochaine<=td).length,enRetard:act.filter(x=>x.prochaine&&x.prochaine<td).length,enCours:act.length,inscrits:(d.prospects.inscrits||0)+(doc.statut==="inscrit"?1:0)})}
  else if(op.coll==="raids"){d.marge=d.marge||{liste:[],objectif:30};const ca=+doc.ca||0,couts=+doc.couts||0;up(d.marge.liste,Object.assign({},doc,{marge:Math.round((ca-couts)*100)/100,pct:ca>0?Math.round((ca-couts)/ca*1000)/10:null}));const f=d.marge.liste.filter(r=>r.ca>0&&r.pct!=null).sort((a,b)=>String(b.fin||b.debut||"").localeCompare(String(a.fin||a.debut||"")));d.marge.dernier=f[0]||null;d.marge.nombre=f.length;d.marge.moyenne=f.length?Math.round(f.reduce((s,r)=>s+r.pct,0)/f.length*10)/10:null}
  else if(op.coll==="chantiers"){d.chantiers=d.chantiers||{liste:[]};if(id==="EDL")d.chantiers.etatDesLieux=doc.majLe||today();else{up(d.chantiers.liste,doc);const l=d.chantiers.liste;Object.assign(d.chantiers,{enCours:l.filter(x=>x.statut==="en cours").length,attente:l.filter(x=>x.statut==="attente").length,faits:l.filter(x=>x.statut==="fait").length})}}
  else if(op.coll==="reseaux"){d.reseaux=d.reseaux||{liste:[]};up(d.reseaux.liste,doc);d.reseaux.notifications=d.reseaux.liste.reduce((s,r)=>s+(+r.notifications||0),0);d.reseaux.prochain=d.reseaux.liste.map(r=>r.prochain).filter(Boolean).sort()[0]||"";d.reseaux.renseigne=true}
  else if(op.coll==="reglages"){d.reglages=d.reglages||{};d.reglages[id]=doc.valeur;if(d.banque){if(id==="TRESO_OBJECTIF")d.banque.objectif=+doc.valeur;if(id==="TRESO_ALERTE")d.banque.alerte=+doc.valeur}}
  else if(op.coll==="indicateurs"){d.indicateurs=d.indicateurs||{};for(const k in d.indicateurs){const i=d.indicateurs[k].findIndex(x=>x.id===id);if(i>=0)Object.assign(d.indicateurs[k][i],doc)}}
  else if(op.coll==="commandes"){d.commandes=d.commandes||{liste:[]};up(d.commandes.liste,doc);const l=d.commandes.liste,n=s=>l.filter(x=>x.statut===s).length,sum=a=>Math.round(a.reduce((s,x)=>s+(+x.prix||0),0)*100)/100;Object.assign(d.commandes,{recues:n("reçue"),enCours:n("en cours"),livrees:n("livrée"),payees:n("payée"),montant:sum(l.filter(x=>x.statut!=="annulée")),aEncaisser:sum(l.filter(x=>x.statut==="livrée"))})}
  else if(op.coll==="positions"){d.position=d.position||{balise:"a_venir"};d.position.telephone={lat:+doc.lat,lon:+doc.lon,at:doc.date,precision:doc.precision,source:"telephone"};const i=d.position.inreach;d.position.actuelle=(i&&String(i.at)>=String(doc.date))?i:d.position.telephone}
}
/* ---------- position du téléphone (« Je suis ici », ou toutes les 30 min en raid) ---------- */
function tbIci(auto){if(!navigator.geolocation){toast("Pas de localisation sur cet appareil.");return}
  navigator.geolocation.getCurrentPosition(async g=>{const c=g.coords;await tbWrite("positions","pos-"+AtelierCore.newId(),{date:new Date().toISOString(),lat:Math.round(c.latitude*1e5)/1e5,lon:Math.round(c.longitude*1e5)/1e5,precision:Math.round(c.accuracy||0),source:"telephone",notes:auto?"auto 30 min":"Je suis ici"});if(!auto)toast("Position envoyée.")},
    err=>{if(!auto)toast(err.code===1?"Localisation refusée : autorise-la dans les réglages du téléphone.":"Position introuvable pour l'instant.")},{enableHighAccuracy:true,timeout:20000,maximumAge:60000})}
/* ---------- carte : déplacement et zoom ---------- */
function tbMapVb(svg){return svg.getAttribute("viewBox").split(" ").map(Number)}
function tbMapSet(svg,vb){svg.setAttribute("viewBox",vb.map(v=>v.toFixed(3)).join(" "))}
function tbMapZoom(svg,f,cx,cy){const vb=tbMapVb(svg);const P=tbProj();const nw=Math.max(0.8,Math.min(P.W*1.5,vb[2]*f)),nh=nw*(vb[3]/vb[2]);const rx=cx==null?.5:(cx-vb[0])/vb[2],ry=cy==null?.5:(cy-vb[1])/vb[3];tbMapSet(svg,[vb[0]+(vb[2]-nw)*rx,vb[1]+(vb[3]-nh)*ry,nw,nh])}
function tbMapBind(box){const svg=box&&box.querySelector("svg.tb-map");if(!svg)return;let drag=null,pinch=null;const pt=e=>{const r=svg.getBoundingClientRect(),vb=tbMapVb(svg);const s=Math.max(vb[2]/r.width,vb[3]/r.height);const ox=(r.width-vb[2]/s)/2,oy=(r.height-vb[3]/s)/2;return[vb[0]+(e.clientX-r.left-ox)*s,vb[1]+(e.clientY-r.top-oy)*s,s]};
  svg.addEventListener("pointerdown",e=>{if(e.isPrimary){drag={x:e.clientX,y:e.clientY,vb:tbMapVb(svg)};svg.setPointerCapture(e.pointerId);box.style.cursor="grabbing"}});
  svg.addEventListener("pointermove",e=>{if(!drag||!e.isPrimary)return;const r=svg.getBoundingClientRect();const s=Math.max(drag.vb[2]/r.width,drag.vb[3]/r.height);tbMapSet(svg,[drag.vb[0]-(e.clientX-drag.x)*s,drag.vb[1]-(e.clientY-drag.y)*s,drag.vb[2],drag.vb[3]])});
  const end=()=>{drag=null;box.style.cursor="grab"};svg.addEventListener("pointerup",end);svg.addEventListener("pointercancel",end);
  svg.addEventListener("wheel",e=>{e.preventDefault();const [cx,cy]=pt(e);tbMapZoom(svg,e.deltaY>0?1.25:0.8,cx,cy)},{passive:false});
  svg.addEventListener("touchstart",e=>{if(e.touches.length===2){pinch={d:Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY),vb:tbMapVb(svg)};drag=null}},{passive:true});
  svg.addEventListener("touchmove",e=>{if(pinch&&e.touches.length===2){e.preventDefault();const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);const f=pinch.d/d;const vb=pinch.vb;const nw=Math.max(0.8,vb[2]*f),nh=nw*(vb[3]/vb[2]);tbMapSet(svg,[vb[0]+(vb[2]-nw)/2,vb[1]+(vb[3]-nh)/2,nw,nh])}},{passive:false});
  svg.addEventListener("touchend",()=>{pinch=null},{passive:true});
  svg.querySelectorAll("[data-tb-raid]").forEach(p=>p.addEventListener("click",e=>{if(drag&&(Math.abs(e.clientX-drag.x)>4||Math.abs(e.clientY-drag.y)>4))return;TB.sub=p.dataset.tbRaid;tbRender()}));}

/* ---------- interactions ---------- */
function tbOpen(dom,sub){TB.open=dom;TB.sub=sub||null;tbRender()}
function tbBureau(on){TB.bureau=!!on;document.body.classList.toggle("tb-bureau",TB.bureau);store("tbBureau",TB.bureau);
  try{if(TB.bureau&&document.documentElement.requestFullscreen&&!document.fullscreenElement)document.documentElement.requestFullscreen().catch(()=>{});if(!TB.bureau&&document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}catch(e){}
  tbRender()}
function tbFormData(f){const o={};new FormData(f).forEach((v,k)=>o[k]=typeof v==="string"?v.trim():v);f.querySelectorAll("input[type=checkbox]").forEach(c=>o[c.name]=c.checked);return o}
async function tbSubmit(f){const kind=f.dataset.tbForm,o=tbFormData(f);
  try{
    if(kind==="inscrit"){const sel=f.querySelector("[name=raidId]");const opt=sel&&sel.selectedOptions[0];const raidNom=o.raidId?(opt.dataset.nom||""):o.raid;if(!o.raidId&&!o.raid){toast("Indique le raid.");return}await tbWrite("inscrits","ins-"+AtelierCore.newId(),{raidId:o.raidId||"",raid:raidNom,pilote:tbPrive(o.pilote),acompte:!!o.acompte,solde:!!o.solde,kove:!!o.kove,statut:"inscrit",notes:o.notes||""});toast("Inscrit enregistré.")}
    else if(kind==="prospect"){await tbWrite("prospects","pro-"+AtelierCore.newId(),{prospect:tbPrive(o.prospect),raid:o.raid||"",canal:o.canal||"",dernier:o.dernier||today(),prochaine:o.prochaine||tbPlus(today(),3),statut:"en cours",notes:o.notes||""});toast("Prospect enregistré.")}
    else if(kind==="raid"){const id=tbSlug(o.raid+"-"+(o.debut||""));await tbWrite("raids",id,{raid:o.raid,debut:o.debut||"",fin:o.fin||"",pilotes:o.pilotes===""?null:+o.pilotes,ca:+o.ca,couts:+o.couts,notes:o.notes||""});toast("Bilan enregistré.")}
    else if(kind==="chantier"){await tbWrite("chantiers","ch-"+AtelierCore.newId(),{chantier:o.chantier,agent:o.agent||"",statut:o.statut||"en cours",priorite:+o.priorite||5,notes:""});toast("Chantier enregistré.")}
    else if(kind==="edl"){await tbWrite("chantiers","EDL",{chantier:"État des lieux (dernière mise à jour)",agent:"Chef d'équipe",statut:"info",majLe:o.majLe||today()});toast("Date mise à jour.")}
    else if(kind==="reseau"){await tbWrite("reseaux",f.dataset.id,{notifications:o.notifications===""?null:+o.notifications,dernier:o.dernier||"",prochain:o.prochain||""});toast("Réseau mis à jour.")}
    else if(kind==="indicateur"){await tbWrite("indicateurs",f.dataset.id,{valeur:o.valeur||"",max:o.max===""?null:+o.max,etat:o.etat||""});toast("Mesure enregistrée.")}
    else if(kind==="reglages"){for(const k in o)if(/^(TRESO_|MAIL_)/.test(k))await tbWrite("reglages",k,{valeur:String(o[k])});toast("Réglages enregistrés.")}
    else if(kind==="commande"){await tbWrite("commandes","com-"+AtelierCore.newId(),{pilote:tbPrive(o.pilote),projet:o.projet||"",zone:o.zone||"",jours:o.jours===""?null:+o.jours,km:o.km===""?null:+o.km,niveau:o.niveau||"",date:o.date||today(),prix:o.prix===""?null:+o.prix,statut:"reçue",lien:o.lien||"",notes:o.notes||""});toast("Commande enregistrée.")}
  }catch(e){dbErr(e)}
}
async function tbAction(b){const a=b.dataset.tbAct,id=b.dataset.id;
  if(a==="back"){TB.open=null;TB.sub=null;tbRender();return}
  if(a==="refresh"){tbPull(true);return}
  if(a==="bureau"){tbBureau(!TB.bureau);return}
  if(a==="ins-form"){const box=$("#tbInsForm-"+CSS.escape(b.dataset.raid));if(box){box.innerHTML=box.innerHTML?"":tbFormInscrit(b.dataset.raid)}return}
  if(a==="ins-toggle"){await tbWrite("inscrits",id,{[b.dataset.f]:b.dataset.v!=="1"});return}
  if(a==="ins-annule"){if(!confirmTwice("ins-"+id)){toast("Touche encore une fois pour retirer ce pilote.");return}await tbWrite("inscrits",id,{statut:"annulé"});return}
  if(a==="pro-relance"){await tbWrite("prospects",id,{dernier:today(),prochaine:tbPlus(today(),7)});toast("Relance notée : prochaine dans 7 jours.");return}
  if(a==="pro-statut"){await tbWrite("prospects",id,{statut:b.dataset.s});return}
  if(a==="ch-statut"){await tbWrite("chantiers",id,{statut:b.dataset.s});return}
  if(a==="pos-ici"){tbIci(false);return}
  if(a==="pos-suivi"){store("tbSuivi",!!b.checked);toast(b.checked?"Position envoyée toutes les 30 min tant que l'appli est ouverte.":"Suivi arrêté.");if(b.checked)tbIci(true);return}
  if(a==="carte-raid"){TB.sub=b.dataset.raid;tbRender();return}
  if(a==="zoom"){const svg=$("#tbMapBox svg");if(!svg)return;const z=b.dataset.z;if(z==="in")tbMapZoom(svg,0.7);else if(z==="out")tbMapZoom(svg,1.4);else if(z==="all"){const P=tbProj();tbMapSet(svg,[0,0,P.W,P.H])}else{TB.sub=TB.sub||tbRaidActif();tbRender()}return}
  if(a==="qonto-test"){const m=$("#tbQontoMsg");if(!App.online()){toast("Il faut du réseau.");return}if(m)m.textContent="Vérification…";try{const j=await AtelierCore.call("tableau.qonto.test",{});if(m)m.textContent=j.etat==="ok"?`Connecté : ${j.comptes} compte(s). Le tableau se met à jour.`:j.etat==="a_connecter"?"Les propriétés QONTO_ORG et QONTO_KEY ne sont pas encore posées dans la passerelle.":`Refus : ${j.message||j.etat}`;if(j.etat==="ok")tbPull(true)}catch(e){if(m)m.textContent="Impossible : "+(e.message||e.code)}return}
}

(self.ATELIER_MODULES=self.ATELIER_MODULES||[]).push({
  id:"tableau",views:["tableau"],
  init(){
    const root=$("#v-tableau");if(!root)return;
    root.addEventListener("click",e=>{const o=e.target.closest("[data-tb-open]");if(o){tbOpen(o.dataset.tbOpen,o.dataset.sub);return}const g=e.target.closest("[data-tb-go]");if(g){go(g.dataset.tbGo);return}const f=e.target.closest("[data-tb-fiche]");if(f){S.fiche=f.dataset.tbFiche;go("fiche");return}const b=e.target.closest("[data-tb-act]");if(b)tbAction(b)});
    root.addEventListener("submit",e=>{const f=e.target.closest("form[data-tb-form]");if(f){e.preventDefault();tbSubmit(f)}});
    root.addEventListener("change",e=>{const s=e.target.closest("select[data-tb-act=com-statut]");if(s)tbWrite("commandes",s.dataset.id,{statut:s.value})});
    // Fond de carte et tracés : servis par la passerelle au guide (tableau.carte), gardés en IndexedDB ; jamais un fichier statique ni un service en ligne.
    AtelierCore.kv.get("tableau_carte").then(j=>{if(j&&j.pays){TB.carte=j;if(S.view==="tableau")tbRender()}}).catch(()=>{});
    setInterval(()=>{if(store("tbSuivi")===true&&App.key&&S.role==="guide"&&!document.hidden)tbIci(true)},30*60000);
    // Quand on quitte le tableau : thème de l'appli rendu, mode bureau mis en pause.
    TB.obs=new MutationObserver(()=>{document.body.classList.toggle("tb-view",!root.hidden);if(root.hidden){document.documentElement.removeAttribute("data-theme");document.body.classList.remove("tb-bureau")}else if(TB.bureau)document.body.classList.add("tb-bureau")});
    TB.obs.observe(root,{attributes:true,attributeFilter:["hidden"]});
    document.addEventListener("fullscreenchange",()=>{if(!document.fullscreenElement&&TB.bureau&&S.view==="tableau"){TB.bureau=false;document.body.classList.remove("tb-bureau");store("tbBureau",false);tbRender()}});
    AtelierCore.kv.get("tableau").then(x=>{if(x&&x.d){TB.d=x.d;TB.at=x.at||0;if(S.view==="tableau")tbRender()}}).catch(()=>{});
    TB.bureau=store("tbBureau")===true&&window.innerWidth>=900;
    setInterval(()=>{if(!document.hidden&&App.online()&&App.key&&S.role==="guide"&&S.view==="tableau"&&Date.now()-TB.at>290000)tbPull(false)},60000);
    window.addEventListener("online",()=>{if(S.view==="tableau")setTimeout(()=>tbPull(false),500)});
    document.addEventListener("visibilitychange",()=>{if(!document.hidden&&S.view==="tableau"&&Date.now()-TB.at>60000)tbPull(false)});
  },
  render(){tbRender();if(App.online()&&App.key&&S.role==="guide"&&Date.now()-TB.at>60000&&!TB.busy)tbPull(false)}
});
